#!/bin/bash
# Evaluation script — the standard way to evaluate work in this environment.
#
# Self-contained in eval/: it never imports method/.  Every solver registered
# in outputs/solvers/*.json ({"command": [..., "{sessions}", ..., "{output}"]})
# is run on the visible train sessions generated by eval/train/, and every
# metric is recomputed from the solver's raw candidate scores.
#
# OUTPUT CONTRACT: writes scoring/scores.json, nested as
#   {"experiments": {<experiment>: {"results": {<solver>: {<metric>: value}}}}}
# with experiment and metric names matching scoring/reference.json.
#
# Usage:
#   bash scripts/evaluate.sh

set -e

cd /home/user

mkdir -p scoring

python eval/train/evaluate_cursor.py --solvers-dir outputs/solvers --scores scoring/scores.json
